CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_seed_dummy_usuarios_500`()
BEGIN
    DECLARE v_i INT DEFAULT 1;

    START TRANSACTION;

    WHILE v_i <= 500 DO

        INSERT INTO usuario
        (
            login,
            senha_hash,
            ativo,
            criado_em
        )
        VALUES
        (
            CONCAT('seed_user_', v_i),
            '',
            1,
            NOW(6)
        )
        ON DUPLICATE KEY UPDATE login = login;

        SET v_i = v_i + 1;

    END WHILE;

    COMMIT;
END ;;
